    {
        ArgumentNullException.ThrowIfNull(row);
        if (row.Tipo != NomeJson.De(TipoDeItem.Medalha))
        {
            throw new InvalidOperationException($"O item {row.Codigo} é {row.Tipo}, não medalha.");
        }

        return new ItemMedalha
        {
