usePremios.ts
import { StyleSheet, Text, View } from "react-native";

import { Medalhao } from "../premios/Medalhao";
import { rotulosDeRaridade, rotulosDeTier } from "../premios/rotulos";
import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { tiers, type Tier } from "../theme/tokens";
import {
  detalheDaLinha,
  glifoDe,
  pontosDaLinha,
  raridadeDe,
  textoDaRaridade,
  type ItemDoAluno,
} from "./montagem";

// Uma linha da lista de Troféus (prancheta trofeus-*.png): medalhão com tier e raridade,
// nome, "Tier · Raridade · x% dos alunos", o critério ou de onde veio, e os pontos. O que
// falta aparece apagado, com o valor do catálogo sem o "+".
export function LinhaDePremio({ item }: { item: ItemDoAluno }) {
  const { colors, name } = useTheme();
  const tier = item.tier as Tier;
  const raridade = raridadeDe(item);
  const obtido = item.obtidos.length > 0;

  return (
    <View
      testID={`premio-${item.codigo}`}
      accessible
      accessibilityLabel={[
        item.nome,
        rotulosDeTier[tier],
        raridade && rotulosDeRaridade[raridade],
        obtido ? "obtido" : "não obtido",
      ]
        .filter(Boolean)
        .join(", ")}
      style={[styles.linha, { borderBottomColor: colors.line }]}
    >
      <View style={!obtido && styles.apagado}>
        <Medalhao tier={tier} glifo={glifoDe(item)} raridade={raridade} />
      </View>
      <View style={styles.texto}>
        <Text style={[textStyles.secao, { color: colors.ink }]}>
          {item.nome}
        </Text>
        <Text style={textStyles.legenda}>
          <Text style={{ color: tiers[tier].texto[name] }}>
            {rotulosDeTier[tier]}
          </Text>
          {raridade && item.raridade && (
            <Text style={{ color: colors.ink2 }}>
              {` · ${rotulosDeRaridade[raridade]} · ${textoDaRaridade(item.raridade.percentual)}`}
            </Text>
          )}
        </Text>
        <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
          {detalheDaLinha(item)}
        </Text>
      </View>
      <Text
        style={[
          textStyles.pontos,
          { color: obtido ? colors.ink : colors.ink3 },
        ]}
      >
        {pontosDaLinha(item)}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  linha: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    paddingVertical: 14,
    borderBottomWidth: 1,
  },
  apagado: { opacity: 0.45 },
  texto: { flex: 1, gap: 2 },
});
      return {
        codigo: familia.codigo,
        titulo: familia.nome,
        resumo: `${itens.filter(obtido).length} de ${itens.length} · ${formatarPontos(
          itens.reduce((soma, item) => soma + pontosObtidos(item), 0),
        )}`,
        passos: itens.map((item, indice) => ({
          id: item.codigo,
          // Como na prancheta, o passo diz o tier; o nome do item está na lista abaixo.
          rotulo: rotulosDeTier[item.tier as Tier],
          tier: item.tier as Tier,
          glifo: glifoDe(item),
          obtido: obtido(item),
          detalhes: obtido(item)
            ? [`+${formatarNumero(pontosObtidos(item))} pts`]
            : indice === proximo
              ? [`${formatarNumero(item.pontos)} pts`, "próximo"]
              : [`${formatarNumero(item.pontos)} pts`],
        })),
      };
    });
}

export const glifoDe = (item: ItemDoAluno): "taca" | "fita" =>
  item.tipo === "medalha" ? "fita" : "taca";

export const raridadeDe = (item: ItemDoAluno) =>
  item.raridade?.nivel as Raridade | undefined;

export const pontosDaLinha = (item: ItemDoAluno) =>
  obtido(item)
    ? `+${formatarNumero(pontosObtidos(item))}`
    : formatarNumero(item.pontos);

// Números no formato brasileiro: 15.020 (identidade-visual.md).
export const formatarNumero = (n: number) => n.toLocaleString("pt-BR");

export const formatarPontos = (n: number) => `${formatarNumero(n)} pts`;

// "12,5% dos alunos": o texto da raridade (produto.md 4.3).
export const textoDaRaridade = (percentual: number) =>
  `${percentual.toLocaleString("pt-BR", { maximumFractionDigits: 1 })}% dos alunos`;

// A linha de detalhe: o critério, ou, na medalha obtida, onde e quando veio a mais recente.
export function detalheDaLinha(item: ItemDoAluno): string {
  const [maisRecente] = item.obtidos;
  if (!maisRecente || !maisRecente.materia) {
    return item.criterio;
  }

  const vezes =
    item.obtidos.length > 1 ? ` · ${item.obtidos.length} vezes` : "";
  const bimestre = maisRecente.bimestre
    ? ` · ${maisRecente.bimestre}º bimestre`
    : "";
  return `${maisRecente.materia}${bimestre}${vezes}`;
}

